class="ielts-q-badge">18</strong> <span>a reference to the problems a bike-sharing scheme was intended to solve</span></td>
                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="18" name="question_18" value="A"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="18" name="question_18" value="B"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="18" name="question_18" value="C"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="18" name="question_18" value="D"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="18" name="question_18" value="E"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="18" name="question_18" value="F"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="18" name="question_18" value="G"></td></tr></tbody></table>                                                                                                                                                                                        </div>
