-- Section 1413: Reading Passage 3: Motivational factors and the hospitality industry
INSERT INTO sections (id, test_id, type, title, instructions, audio_url, passage_text, order_index) VALUES
(1413, 141, 'reading', 'Reading Passage 3: Motivational factors and the hospitality industry', '<div class="ielts-reading-container"><h2 class="ielts-reading-question-section-heading">
                                            Questions 27-31                                                                                                                                                
                                                                                                                                    </h2>
                                        <div class="ielts-reading-question-section-content">
                                            <p>Look at the following statements and the list of researchers below.</p>
<p>Match each statement with the correct researcher, <strong>A-F</strong>.</p>
<p><em>Write the correct letter, <strong>A-F</strong>, in boxes on your answer sheet.</em></p>
<p><strong>NB</strong>  <em>You may use any letter more than once.</em></p>
<p><strong>List of Researchers</strong></p>
<p><strong>A</strong>   Pfeffer</p>
<p><strong>B</strong>   Lucas</p>
<p><strong>C</strong>   Maroudas et al.</p>
<p><strong>D</strong>   Ng and Sorensen</p>
<p><strong>E</strong>   Enz and Siguaw</p>
<p><strong>F</strong>   Deery</p>
                                        </div>
                                        <div class="ielts-reading-questions">
                                                                                                                                                                                                <table class="ielts-reading-matching-table"><thead><tr><th></th><th>A</th><th>B</th><th>C</th><th>D</th><th>E</th><th>F</th></tr></thead><tbody><tr class="ielts-reading-question-item"><td class="ielts-reading-matching-question-cell"><strong id="ielts-reading-question-number-27" class="ielts-q-badge">27</strong> <span>Hotel managers need to know what would encourage good staff to remain.</span></td>
                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="27" name="question_27" value="A"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="27" name="question_27" value="B"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="27" name="question_27" value="C"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="27" name="question_27" value="D"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="27" name="question_27" value="E"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="27" name="question_27" value="F"></td></tr>                                                                                                                                                                                                                                                                                                    <tr class="ielts-reading-question-item"><td class="ielts-reading-matching-question-cell"><strong id="ielts-reading-question-number-28" class="ielts-q-badge">28</strong> <span>The actions of managers may make staff feel they shouldn’t move to a different employer.</span></td>
