-- Section 1421: Reading Passage 1: Alexander Henderson (1831-1913)
INSERT INTO sections (id, test_id, type, title, instructions, audio_url, passage_text, order_index) VALUES
(1421, 142, 'reading', 'Reading Passage 1: Alexander Henderson (1831-1913)', '<div class="ielts-reading-container"><h2 class="ielts-reading-question-section-heading">
                                            Questions 1-8                                                                                                                                                                                                    
                                                                                                                                    </h2>
                                        <div class="ielts-reading-question-section-content">
                                            <p>Do the following statements agree with the information given in the Reading Passage?</p>
<p>In boxes on your answer sheet, write</p>
<p><strong>TRUE</strong>               if the statement agrees with the information</p>
<p><strong>FALSE</strong>              if the statement contradicts the information</p>
<p><strong>NOT GIVEN</strong>    if there is no information on this</p>
                                        </div>
                                        <div class="ielts-reading-questions">
                                                                                                                                                                                            <div class="ielts-standalone-q" data-qnum="1"><div class="ielts-q-header"><strong class="ielts-q-badge">1</strong><span class="ielts-q-title"><span>Henderson rarely visited the area around Press estate when he was younger.</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="1" name="question_1" value="TRUE"><span class="ielts-radio-text"><strong>TRUE</strong> </span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="1" name="question_1" value="FALSE"><span class="ielts-radio-text"><strong>FALSE</strong> </span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="1" name="question_1" value="NOT GIVEN"><span class="ielts-radio-text"><strong>NOT GIVEN</strong> </span></label></div></div><div class="ielts-standalone-q" data-qnum="2"><div class="ielts-q-header"><strong class="ielts-q-badge">2</strong><span class="ielts-q-title"><span>Henderson pursued a business career because it was what his family wanted.</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="2" name="question_2" value="TRUE"><span class="ielts-radio-text"><strong>TRUE</strong> </span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="2" name="question_2" value="FALSE"><span class="ielts-radio-text"><strong>FALSE</strong> </span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="2" name="question_2" value="NOT GIVEN"><span class="ielts-radio-text"><strong>NOT GIVEN</strong> </span></label></div></div><div class="ielts-standalone-q" data-qnum="3"><div class="ielts-q-header"><strong class="ielts-q-badge">3</strong><span class="ielts-q-title"><span>Henderson and Notman were surprised by the results of their 1865 experiment.</span></div><div class=