-- Section 1431: Reading Passage 1: The concept of intelligence
INSERT INTO sections (id, test_id, type, title, instructions, audio_url, passage_text, order_index) VALUES
(1431, 143, 'reading', 'Reading Passage 1: The concept of intelligence', '<div class="ielts-reading-container"><h2 class="ielts-reading-question-section-heading">
