-- Section 1432: Reading Passage 2: Saving bugs to find new drugs
INSERT INTO sections (id, test_id, type, title, instructions, audio_url, passage_text, order_index) VALUES
(1432, 143, 'reading', 'Reading Passage 2: Saving bugs to find new drugs', '<div class="ielts-reading-container"><h2 class="ielts-reading-question-section-heading">
                                            Questions 14-20                                                                                                                                                
                                                                                                                                    </h2>
                                        <div class="ielts-reading-question-section-content">
                                            <p>The Reading Passage has nine paragraphs, <strong>A-I</strong></p>
<p>Which paragraph contains the following information?</p>
<p><em>Write the correct letter, <strong>A-I</strong>, in boxes on your answer sheet.</em></p>
