                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="15" name="question_15" value="A"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="15" name="question_15" value="B"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="15" name="question_15" value="C"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="15" name="question_15" value="D"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="15" name="question_15" value="E"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="15" name="question_15" value="F"></td></tr>                                                                                                                                                                                                                                                                                                    <tr class="ielts-reading-question-item"><td class="ielts-reading-matching-question-cell"><strong id="ielts-reading-question-number-16" class="ielts-q-badge">16</strong> <span>mention of two ways of learning about animals other than visiting them in zoos</span></td>
